147	impl Service<DatabendRequest> for DatabendService {
148	    type Response = DatabendResponse;
149	    type Error = DatabendError;
150	    type Future = BoxFuture<'static, Result<Self::Response, Self::Error>>;
151	
152	    fn poll_ready(&mut self, _cx: &mut Context) -> Poll<Result<(), Self::Error>> {
153	        Poll::Ready(Ok(()))
154	    }
155	
156	    fn call(&mut self, request: DatabendRequest) -> Self::Future {
157	        let service = self.clone();
158	
159	        let future = async move {
160	            let metadata = request.get_metadata().clone();
161	            let protocol = service.client.scheme.as_str();
162	            let host_port = format!("{}:{}", service.client.host, service.client.port);
163	            let endpoint = host_port.as_str();
164	            let byte_size = request.data.len();
165	            service.insert_with_stage(request.data).await?;
166	            emit!(EndpointBytesSent {
167	                byte_size,
168	                protocol,
169	                endpoint,
170	            });
171	            Ok(DatabendResponse { metadata })
172	        };
173	        Box::pin(future)
174	    }
175	}
